    external_id text, slug text, name text, description text, brand text, model text, category_slug text,
    source_url text, source_rank_by_sport jsonb, sports text[], attributes jsonb, football_types text[],
    source_name text, source_checked_at date
  )
),
inserted_products as (
  insert into public.products (external_id, slug, name, description, brand, model, category_id, platform_id, source_url, price, currency, status, attributes, football_types, source_name, source_checked_at)
  select seed.external_id, seed.slug, seed.name, seed.description, seed.brand, seed.model, category.id, 'amazon', seed.source_url, null, 'BRL', 'draft', seed.attributes, seed.football_types, seed.source_name, seed.source_checked_at
  from seed join public.categories category on category.slug = seed.category_slug
  on conflict (external_id) do nothing
  returning id, external_id
),
inserted_sports as (
  insert into public.product_sports (product_id, sport_id)
  select inserted_products.id, sport_id
  from inserted_products join seed using (external_id)
  cross join lateral unnest(seed.sports) as sport(sport_id)
  on conflict (product_id, sport_id) do nothing
  returning product_id
)
insert into public.product_rankings (product_id, sport_id, source_name, rank, observed_at)
select inserted_products.id, sport_rank.key, seed.source_name, sport_rank.value::integer, seed.source_checked_at
from inserted_products join seed using (external_id)
cross join lateral jsonb_each_text(seed.source_rank_by_sport) as sport_rank
on conflict (product_id, sport_id, source_name, observed_at) do nothing;

commit;
